/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_custQuotationJour">_custQuotationJour</param>
protected void clearQuotationEmailAttachment(CustQuotationJour      _custQuotationJour)
{
    AVAQuotationEmailAttachments            quotationEmailAttachments;
    str 255                                 quotationFilter = '*' + _custQuotationJour.KCS_QuotationId + '*';

    ttsbegin;
    delete_from quotationEmailAttachments
        where quotationEmailAttachments.UserId == curUserId()
        //   && quotationEmailAttachments.SessionId == SessionId()
          && quotationEmailAttachments.Filename like quotationFilter;
    ttscommit;

}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_custQuotationJour">_custQuotationJour</param>
/// <param name = "_reportName">_reportName</param>
/// <returns>Stream</returns>
public static System.IO.Stream      getReportFromMemory(CustQuotationJour     _custQuotationJour, String255         _reportName)
{
    AVAERReportToMemory         reportToMemory;
    System.IO.Stream            reportStream;

    select firstonly reportToMemory
        where reportToMemory.RefRecId  == _custQuotationJour.RecId
           && reportToMemory.RefTableId == tableNum(CustQuotationJour)
           && reportToMemory.ReportName == _reportName;

    if (reportToMemory.RecId)
    {
        Binary archiveBinary = Binary::constructFromContainer(reportToMemory.Report);
        reportStream = archiveBinary.getMemoryStream();
    }

    return reportStream;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_custQuotationJour">_custQuotationJour</param>
/// <returns>Stream</returns>
protected System.IO.Stream      getAttachment(CustQuotationJour     _custQuotationJour)
{
    AVAQuotationEmailAttachments            quotationEmailAttachments;
    System.IO.Stream                        attachFileStream;
    str 255                                 quotationFilter = '*' + _custQuotationJour.KCS_QuotationId + '*';

    select firstonly quotationEmailAttachments
        where quotationEmailAttachments.UserId == curUserId()
           && quotationEmailAttachments.Filename like quotationFilter;

    if (!quotationEmailAttachments.RecId)
    {
        Binary archiveBinary = Binary::constructFromContainer(quotationEmailAttachments.FileBlobdata);
        attachFileStream = archiveBinary.getMemoryStream();
    }

    return attachFileStream;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_docuRef">_docuRef</param>
/// <returns>Stream</returns>
protected System.IO.Stream  getAttchmentFromDocuRef(DocuRef   _docuRef)
{
    System.IO.Stream                        attachFileStream;

    if (_docuRef.ValueRecId)
    {
        attachFileStream = DocumentManagement::getAttachmentStream(_docuRef);
    }

    return attachFileStream;
}

/// <summary>
///    AVA <c>sendBPEmail</c> method.
/// </summary>
/// <param name="_emailFrom">
///    <c>Email</c> as type
/// </param>
/// <param name="_emailTo">
///    <c>Email</c> as type
/// </param>
/// <param name="_subject">
///    <c>str</c> as type
/// </param>
/// <param name="_body">
///    <c>str</c> as type
/// </param>
/// <param name="_emailCC">
///    <c>Email</c> as type
/// </param>
/// <param name="_nonInteractive">
///    <c>boolean</c> as type
/// </param>
/// <param name="_emailSendingActivated">
///    <c>boolean</c> as type
/// </param>
/// <param name="_infoMessageActivated">
///    <c>boolean</c> as type
/// </param>
/// <param name="_custQuotationJour">
///   _custQuotationJour
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
boolean sendEREmail(Email   _emailFrom,
                    Email   _emailTo,
                    str     _subject,
                    str     _body,
                    Email   _emailCC = '',
                    boolean _emailSendingActivated  = true,
                    boolean _nonInteractive         = false,
                    boolean _infoMessageActivated   = false,
                    CustQuotationJour   _custQuotationJour = null)
{
    boolean                 retVal;

    SysMailerMessageBuilder messageBuilder;

    PrintMgmtReportFormat           printMgmtReportFormat;
    PrintMgmtDocInstance            printMgmtDocInstance;
    PrintMgmtSettings               printMgmtSettings;
    DocuRef                         docuRef;
    DocuType                        docuType;
    DocuValue                       docuValue;
    HcmWorker                       avaWorkerSalesTaker;
    str                             avaAttachmentName;


    retVal = true;

    if(_emailSendingActivated)
    {
        messageBuilder = new SysMailerMessageBuilder();

        try
        {
            avaWorkerSalesTaker = HcmWorker::find(_custQuotationJour.WorkerSalesTaker);
            avaAttachmentName = strFmt('%1-%2', avaWorkerSalesTaker.PersonnelNumber, _custQuotationJour.KCS_QuotationId);

            messageBuilder.setBody(_body, true);
            messageBuilder.setSubject(_subject);
            messageBuilder.addTo(_emailTo);

            // Note: not calling setFrom() defaults to the current user for SMTP client, whereas
            // when sent to Outlook any setFrom() value will be ignored since profiles on the client are used
            messageBuilder.setFrom(_emailFrom);

            select firstonly printMgmtReportFormat
                where printMgmtReportFormat.DocumentType == PrintMgmtDocumentType::Quotation
                join printMgmtSettings
                where printMgmtSettings.ReportFormat == printMgmtReportFormat.RecId
                    join printMgmtDocInstance
                        where printMgmtDocInstance.RecId == printMgmtSettings.ParentId
                && printMgmtDocInstance.PrintType == PrintMgmtDocInstanceType::Original;

            System.IO.Stream        attachmentStream = AVAEREmailCreationHelper::getReportFromMemory(_custQuotationJour,printMgmtReportFormat.Name);

            if (attachmentStream)
            {
                avaAttachmentName += '.pdf';
                messageBuilder.addAttachment(attachmentStream,avaAttachmentName);
            }

            /*select firstonly printMgmtReportFormat
                where printMgmtReportFormat.DocumentType == PrintMgmtDocumentType::Quotation
                join printMgmtSettings
                where printMgmtSettings.ReportFormat == printMgmtReportFormat.RecId
                    join printMgmtDocInstance
                        where printMgmtDocInstance.RecId == printMgmtSettings.ParentId
                && printMgmtDocInstance.PrintType == PrintMgmtDocInstanceType::Copy;    */

            AVASalesParameters          avaSalesParameters = AVASalesParameters::find();
            select firstonly printMgmtReportFormat
                where printMgmtReportFormat.Name  == avaSalesParameters.SalesQuotationExcelReport;

            attachmentStream = AVAEREmailCreationHelper::getReportFromMemory(_custQuotationJour,printMgmtReportFormat.Name);

            avaAttachmentName = strFmt('%1-%2', avaWorkerSalesTaker.PersonnelNumber, _custQuotationJour.KCS_QuotationId);
            if (attachmentStream)
            {
                avaAttachmentName += '.xlsx';
                messageBuilder.addAttachment(attachmentStream,avaAttachmentName);
            }

            while select docuRef
                where docuRef.RefTableId == _custQuotationJour.TableId
                   && docuRef.RefRecId   == _custQuotationJour.RecId
                   && docuRef.Restriction == DocuRestriction::External
                    join docuType
                        where docuType.TypeId  == docuRef.TypeId
                          && docuType.TypeGroup == DocuTypeGroup::File
                                join docuValue
                                    where docuValue.RecId == docuRef.ValueRecId
            {
                attachmentStream = this.getAttchmentFromDocuRef(docuRef);
                if (attachmentStream)
                {
                    messageBuilder.addAttachment(attachmentStream,docuValue.OriginalFileName);
                }
            }

            if (sendGAEB)
            {
                select firstOnly docuRef
                 join docuValue
                 where docuRef.RefTableId     == _custQuotationJour.TableId                &&
                       docuRef.RefRecId       == _custQuotationJour.RecId                  &&
                       docuValue.RecId        == docuRef.ValueRecId                     &&
                      (docuValue.FileType ==  'd94' || docuValue.FileType == 'p94');

                attachmentStream = this.getAttchmentFromDocuRef(docuRef);
                if (attachmentStream)
                {
                    messageBuilder.addAttachment(attachmentStream,docuValue.originalFileName);
                }
            }

            if(_emailCC != '')
            {
                messageBuilder.addCc( strReplace(_emailCC, ',', ';'));
            }

            //messageBuilder.addAttachmentFromFile(

            // Open the generated email in the configured client
            if(_nonInteractive)
            {
                // Try using sendNonInteractive method too
                retVal = SysMailerFactory::sendNonInteractive(messageBuilder.getMessage());

            }
            else
            {
                // Sends a message interactively, allowing the user to view and modify the message before
                //retVal = SysMailerFactory::sendInteractive(messageBuilder.getMessage());
                AVASysmailerEML     avaSysMailerEML = new AVASysmailerEML();
                AVASysmailerEML.sendInteractive(messageBuilder.getMessage(),_custQuotationJour.QuotationDocNum + '_' + date2Str(_custQuotationJour.QuotationDate,321,2,DateSeparator::None,2,DateSeparator::None,4));
            }

        }
        catch (Exception::Error)
        {
            throw error(strFmt("@NDX:NXABPInfoEmailSubjectNotSent", _emailTo + ':' + _subject));
        }
    }
    if(_infoMessageActivated)
    {
        info(strFmt("@NDX:NXAQuotationEmailContentInfo", _emailFrom, _emailTo, _emailCC, _subject, _body));
    }

    return retVal;
}

public System.IO.Stream  getGAEBAttachment(CustQuotationJour    _custQuotationJour)
{
    DocuRef     docuRef;
    DocuValue   docuValue;

    select firstOnly1 docuRef 
         join docuValue 
         where docuRef.RefTableId     == _custQuotationJour.TableId                &&
               docuRef.RefRecId       == _custQuotationJour.RecId                  &&
               docuValue.RecId        == docuRef.ValueRecId                     &&
               (docuValue.FileType == 'd94' || docuValue.FileType == 'p94')     &&
               docuRef.KCS_GAEBImport == NoYes::Yes                             &&
               docuRef.typeid         == smmParametersTable::find().KCS_DocuTypeIdForGAEB;

    return this.getAttchmentFromDocuRef(docuRef);
}

/// <summary>
/// creates Email parameters based on provided CustQuotationJour
/// </summary>
/// <param name = "_custQuotationJour">CustQuotationJour</param>
public void createQuotationEmail(CustQuotationJour _custQuotationJour)
{
    str subject, body, quotationId;
    boolean addCC = false;
    Email emailFrom, emailTo, emailCC = '', emailCC_SalesUnit = '';
    AVAQuotationMailSetup mailSetup = AVAQuotationMailSetup::find();
    AVASalesParameters salesParameters = AVASalesParameters::find();
    HcmWorker avaWorkerSalesTaker = HcmWorker::find(_custQuotationJour.WorkerSalesTaker);

    quotationId = strFmt('%1-%2', avaWorkerSalesTaker.PersonnelNumber, _custQuotationJour.KCS_QuotationId);
    subject = strFmt("@NDX:NXAQuotationEmailSubject", quotationId, _custQuotationJour.CustomerRef, _custQuotationJour.KCS_KBVSubject);

    if(mailSetup.RecId != 0)
    {
        body = mailSetup.avaEmailContent(_custQuotationJour.AVAContactPersonId, _custQuotationJour.LanguageId);
        addCC = mailSetup.EmailCC; 
    }
    else
    {
        body = salesParameters.avaEmailContent(_custQuotationJour.AVAContactPersonId, _custQuotationJour.LanguageId);
        addCC = salesParameters.EmailCC;
    }

    UserInfo userInfo;

    select firstonly userInfo
        where userInfo.Id == curUserId();

    //emailFrom = CompanyInfo::find().email();
    emailFrom = userInfo.networkAlias;
    emailTo = _custQuotationJour.AVAEmail;

    if(addCC)
    {
        emailCC = userInfo.networkAlias; //SysUserInfo::find().email;
        //emailCC_SalesUnit = this.getSalesUnitCC(_custQuotationJour.AVASalesUnitId);



        if(emailCC == '')
        {
            warning("@NDX:NXANoUserEmail");
        }
    }

    emailCC_SalesUnit = this.getSalesUnitCC(_custQuotationJour.AVASalesUnitId);

    if(emailCC_SalesUnit != '')
    {
        if (emailCC)
        {
            emailCC += ';';
        }
        emailCC +=emailCC_SalesUnit;
    }

    if(emailFrom == '')
    {
        throw Error("@NDX:NXANoSenderEmail");
    }

    if(emailTo == '')
    {
        throw Error("@NDX:NXANoRecipientEmail");
    }

    boolean sendExcel = _custQuotationJour.salesQuotationTable().AVASendExcel;
    if (!AVAEREmailCreationHelper::checkExistedPrintRun(_custQuotationJour,sendExcel))
    {
         AVAEREmailCreationHelper::printQuotationOrigSSRS(_custQuotationJour);
        if (sendExcel)
        {
            AVAEREmailCreationHelper::printQuotationCopy(_custQuotationJour);
        }
    }

    this.sendEREmail(emailFrom, emailTo, subject, body, emailCC, NoYes::Yes, NoYes::No, NoYes::No, _custQuotationJour);
    this.clearQuotationEmailAttachment(_custQuotationJour);
}

public Email getSalesUnitCC(SalesUnit _salesUnit)
{
    Email ret;
    smmSalesUnitMembers smmMembers;
    HcmWorker hcmWorker;

    while select hcmWorker
        join smmMembers
        where hcmWorker.RecId == smmMembers.SalesPersonWorker
        && hcmWorker.NDX_SalesQuotCC == NoYes::Yes
        && smmMembers.SalesUnitId == _salesUnit
    {
        if(hcmWorker.email() == '')
        {
            continue;
        }

        if(ret != '')
        {
            ret += ', ';
        }

        ret += hcmWorker.email();
    }

    return ret;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_custQuotationJour">_custQuotationJour</param>
/// <param name = "_excelSend">_excelSend</param>
/// <returns>boolean</returns>
public static boolean checkExistedPrintRun(CustQuotationJour        _custQuotationJour, boolean   _excelSend)
{
    AVAERReportToMemory         reportToMemory;
    boolean                     ret;
    ;

    select count(RecId) from reportToMemory
        where reportToMemory.RefTableId == _custQuotationJour.TableId
           && reportToMemory.RefRecId   == _custQuotationJour.RecId;

    ret = (_excelSend && reportToMemory.RecId == 2) ? true : ((!_excelSend && reportToMemory.RecId == 1) ? true : false);

    return ret;
}

