/// <summary>
/// looks up record table to decide which logic to go with
/// </summary>
/// <param name = "_args">Args</param>
public void findRecordTable(Args _args)
{
    switch(_args.dataset())
    {
        case tableNum(CustQuotationJour):
            this.createQuotationEmail(this.parmRecord());
            break;

        default:
            Error(strFmt("@NDX:NXAProcessForTableNotDefined", tableId2Name(_args.dataset())));
    }
}

/// <summary>
///    AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
static void main(Args _args)
{
    #define.sendGAEB('sendGAEB')
    if(!_args.record())
    {
        throw Error("@NDX:NXAFunctionMissingRecord");
    }

    AVAEREmailCreationHelper emailCreation = new AVAEREmailCreationHelper();

    if (_args.parm() == #sendGAEB)
    {
        emailCreation.parmSendGAEB(true);
    }

    emailCreation.parmRecord(_args.record());
    emailCreation.findRecordTable(_args);
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_common">_common</param>
/// <returns>Common</returns>
public Common parmRecord(Common _common = common)
{
    common = _common;

    return common;
}

