/// <summary>
///  N.Freidenberger 05.09.2025
/// </summary>
/// <param name = "_originalStr">_originalStr</param>
/// <returns>str</returns>
public static str replaceUmlaut(str     _originalStr)
{

    str replacedText;
    // Replace Umlauts with ASCII equivalents
    replacedText = strReplace(_originalStr, "ä", "ae");
    replacedText = strReplace(replacedText, "ö", "oe");
    replacedText = strReplace(replacedText, "ü", "ue");
    replacedText = strReplace(replacedText, "Ä", "Ae");
    replacedText = strReplace(replacedText, "Ö", "Oe");
    replacedText = strReplace(replacedText, "Ü", "Ue");
    replacedText = strReplace(replacedText, "ß", "ss");
    return replacedText;

}
